// The changes the engine accepts and their arguments: changes.gen.ts.

package main

import (
	"fmt"
	"reflect"
	"strings"

	"github.com/agrigoryan/quadit/internal/core"
	"github.com/agrigoryan/quadit/internal/engine"
)

// changesSource is the whole of changes.gen.ts. It is written as Prettier
// would format it, so the web app's format check passes it as it is.
func changesSource() string {
	w := &writer{named: map[string]reflect.Type{}}
	var b strings.Builder
	b.WriteString(`// Code generated by "make generate" (cmd/webtypes) from the engine's change
// arguments. DO NOT EDIT.
//
// An argument without "?" is one the change is always refused without; one
// with "?" may be left out, though some are needed only together with others
// (the server says which). Where an argument may be null, null clears the
// field (an engine.Opt argument) or counts as left out (a pointer).

/** A priority may be given by name as well as by number. */
export type PriorityName = `)
	for i, name := range engine.PriorityNames {
		if i > 0 {
			b.WriteString(" | ")
		}
		fmt.Fprintf(&b, "%q", name)
	}
	b.WriteString(";\n\n/** An estimate may be given as a T-shirt size, on any project. */\nexport type TShirtSize = ")
	for i, size := range core.TShirtSizes {
		if i > 0 {
			b.WriteString(" | ")
		}
		fmt.Fprintf(&b, "%q", size)
	}
	b.WriteString(";\n\n/** Each change the server accepts, by name, with its arguments. */\nexport interface Changes {\n")
	for _, name := range engine.ChangeTypes() {
		t, _ := engine.ArgsType(name)
		fmt.Fprintf(&b, "  %s: %s;\n", key(name), w.object(t, 1, true))
	}
	b.WriteString("}\n")
	w.writeNamed(&b)
	return b.String()
}
